enum MBR_REC_TYPE : Int {
  case USER = 1
  case GROUP = 2
}

let _user_compat_prefix : [UInt8] = [0xff, 0xff, 0xee, 0xee, 0xdd, 0xdd, 0xcc, 0xcc, 0xbb, 0xbb, 0xaa, 0xaa, 0x00, 0x00, 0x00, 0x00]
let _group_compat_prefix: [UInt8] = [0xab, 0xcd, 0xef, 0xab, 0xcd, 0xef, 0xab, 0xcd, 0xef, 0xab, 0xcd, 0xef, 0x00, 0x00, 0x00, 0x00]
let COMPAT_PREFIX_LEN = MemoryLayout<uuid_t>.size - MemoryLayout<id_t>.size

func parse_compatibility_uuid(_ uu : uuid_t) -> MemberID? {

  return withUnsafeBytes(of: uu) { ptr in
    let urb = UnsafeRawBufferPointer(start: ptr.baseAddress!, count: COMPAT_PREFIX_LEN)
    if Array(urb) == Array(_user_compat_prefix[0 ..< COMPAT_PREFIX_LEN ]) {
      let rbp = UnsafeRawBufferPointer(start: ptr.baseAddress! + COMPAT_PREFIX_LEN, count: MemoryLayout<id_t>.size)
      let tempID = rbp.bindMemory(to: id_t.self)[0]
      return MemberID.UID(UInt32(bigEndian: tempID))
    } else if Array(urb) == Array(_group_compat_prefix[0 ..< COMPAT_PREFIX_LEN]) {
      let rbp = UnsafeRawBufferPointer(start: ptr.baseAddress! + COMPAT_PREFIX_LEN, count: MemoryLayout<id_t>.size)
      let tempID = rbp.bindMemory(to: id_t.self)[0]
      return MemberID.GID( UInt32(bigEndian: tempID))
    }
    return nil
  }
}

