// implementing the !DS_AVAILABLE path -- because DS_AVAILABLE takes me down a rabbit-hole of private APIs

// #if !DS_AVAILABLE
func compatibility_name_for_id(_ id : id_t, _ rec_type : MBR_REC_TYPE) -> String? {
  let bufsize = sysconf(_SC_GETPW_R_SIZE_MAX)
  if bufsize == -1 {
    return nil
  }

  var buffer = Array(repeating: UInt8(0), count: bufsize)
  if rec_type == .USER {
    var pwd = passwd()
    var pwdp : UnsafeMutablePointer<passwd>? = UnsafeMutablePointer<passwd>(bitPattern: 0)

    if 0 != getpwuid_r(id, &pwd, &buffer, bufsize, &pwdp) {
      return nil;
    }
    return String(cString: pwd.pw_name)
  } else if rec_type == .GROUP {
    var grp = group()
    var grpp : UnsafeMutablePointer<group>? = UnsafeMutablePointer<group>(bitPattern: 0)

    if 0 != getgrgid_r(id, &grp, &buffer, bufsize, &grpp) {
      return nil
    }
    return String(cString: grp.gr_name)
  }
  return nil
}

func compatibility_name_for_uuid(_ u : uuid_t) -> MemberID? {
  if let mi = parse_compatibility_uuid(u) {
    if case let .UID(a) = mi {
      if let n = compatibility_name_for_id(a, .USER) {
        return .USERNAME(n)
      }
    }
  } else {
    return nil
  }
}
// #endif


